function translatedValue(original) {
  const key = original.trim();
  if (!Object.hasOwn(EN, key)) return null;
  // Retain each original text node, its leading/trailing whitespace and markup.
  const start = original.match(/^\s*/)[0];
  const end = original.match(/\s*$/)[0];
  return start + EN[key] + end;
}

/**
 * Call before the application changes the initial DOM, then apply() for English
 * or apply('de') for German. No new nodes or attribute handles are discovered.
 * Detached or subsequently app-owned values are left untouched.
 */
export function captureStaticTranslations() {
  const textHandles = [];
  const attributeHandles = [];
  const walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (node.parentElement?.closest('script, style, noscript, template')) continue;
    const original = node.data;
    const english = translatedValue(original);
    if (english !== null) textHandles.push({ node, original, english, last: original, owned: true });
  }
  for (const element of document.querySelectorAll('[aria-label], [alt], [title], [placeholder], meta[name="description"]')) {
    const names = ['aria-label', 'alt', 'title', 'placeholder'];
    if (element.matches('meta[name="description"]')) names.push('content');
    for (const name of names) {
      if (!element.hasAttribute(name)) continue;
      const original = element.getAttribute(name);
      const english = translatedValue(original);
      if (english !== null) attributeHandles.push({ element, name, original, english, last: original, owned: true });
    }
  }
  return function apply(lang = 'en') {
    if (lang !== 'en' && lang !== 'de') throw new TypeError('Supported languages are en and de.');
    for (const handle of textHandles) {
      if (!handle.owned || !handle.node.isConnected) continue;
      if (handle.node.data !== handle.last) { handle.owned = false; continue; }
      const next = lang === 'en' ? handle.english : handle.original;
      handle.node.data = next;
      handle.last = next;
    }
    for (const handle of attributeHandles) {
      if (!handle.owned || !handle.element.isConnected) continue;
      if (handle.element.getAttribute(handle.name) !== handle.last) { handle.owned = false; continue; }
      const next = lang === 'en' ? handle.english : handle.original;
      handle.element.setAttribute(handle.name, next);
      handle.last = next;
    }
  };
}
